-- Realistic, varied data for exercising the Ashurbanipal DB browser during manual
-- frontend development: five tables spanning uuid/bigint-identity PKs, enums,
-- numeric/real, arrays, inet, date/timestamptz, varchar(n), and NULLs throughout.
-- Idempotent (drops first) so it can be re-run against a live dev db.

create extension if not exists pgcrypto;

drop table if exists sessions cascade;
drop table if exists events cascade;
drop table if exists orders cascade;
drop table if exists products cascade;
drop table if exists users cascade;
drop type if exists order_status cascade;
drop type if exists product_category cascade;

create type order_status as enum ('pending', 'completed', 'cancelled', 'refunded');
create type product_category as enum ('electronics', 'books', 'home', 'toys', 'apparel');

create table users (
    id uuid primary key,
    email text not null unique,
    full_name text not null,
    age smallint,
    is_active boolean not null default true,
    login_count integer not null default 0,
    metadata jsonb not null default '{}',
    last_login_at timestamptz,
    created_at timestamptz not null default now()
);

create table orders (
    id uuid primary key default gen_random_uuid(),
    user_id uuid not null references users(id),
    status order_status not null default 'pending',
    total_cents integer not null,
    discount_pct numeric(5,2),
    tags text[],
    line_items jsonb not null default '[]',
    created_at timestamptz not null default now()
);

create table products (
    id bigint generated always as identity primary key,
    sku varchar(20) not null unique,
    name text not null,
    category product_category not null,
    price numeric(10,2) not null,
    weight_kg real,
    in_stock boolean not null default true,
    description text,
    created_on date not null default current_date
);

create table events (
    id bigint generated always as identity primary key,
    user_id uuid references users(id),
    event_type text not null,
    payload jsonb not null default '{}',
    ip_address inet,
    duration_ms integer,
    occurred_at timestamptz not null default now(),
    is_test boolean not null default false
);

create table sessions (
    id uuid primary key default gen_random_uuid(),
    user_id uuid not null references users(id),
    device_type varchar(20) not null,
    user_agent text not null,
    ip_address inet,
    started_at timestamptz not null,
    ended_at timestamptz
);



